sys_script_client.script:
function onLoad() {
    if (g_form.getValue('source_system') == 'GHSS' || g_form.getValue('source_system') == 'GCS') {

        //MSSCUSTODY-6650-Auto-load On Demand fields on Trade Form Screen

        var synchstatus = g_form.getValue('attribute_sync');
        if (synchstatus == 'Attribute Sync is in progress') {

            g_form.addInfoMessage('Attribute Sync is already in progress');

            return;
        } else {

            var ga = new GlideAjax('x_hsb11_mss_custod.MSSCustodyOnDemandCallUtils');
            ga.addParam('sysparm_name', 'refreshTradeDataClientAPICall');
            ga.addParam('sysparm_tradeID', g_form.getValue('trade_id'));
            ga.addParam('sysparm_tradeSysID', g_form.getUniqueValue());
            ga.getXMLAnswer(response);
        }
    }

    function response(answer) {

    }
}
